wit.client.wit:
world http-client {
import wasi:http/types@0.2.12;
import wasi:http/outgoing-handler@0.2.12;
}

wit.commands.wit:
interface commands {
use types.{json, plugin-error};
run: func(command: string, args: json) -> result<json, plugin-error>;
}
interface progress {
report: func(fraction: option<f32>, message: string);
cancelled: func() -> bool;
}

wit.events.wit:
interface events {
use types.{json};
on-event: func(topic: string, payload: json);
}

wit.hooks.wit:
interface hooks {
use types.{json};
intercept: func(point: string, context: json) -> result<json, string>;
}

wit.ipc.wit:
interface ipc {
use types.{plugin-error};
open: func(endpoint: string) -> result<string, plugin-error>;
send: func(connection: string, bytes: list<u8>) -> result<_, plugin-error>;
receive: func(connection: string, max: u32, timeout-ms: u32) -> result<list<u8>, plugin-error>;
close: func(connection: string) -> result<_, plugin-error>;
%list: func() -> result<list<string>, plugin-error>;
}

wit.plugin.wit:
interface types {
type json = string;
variant plugin-error {
permission-denied(string),
not-found(string),
invalid(string),
failed(string),
unsupported(string),
}
}
interface log {
trace: func(message: string);
debug: func(message: string);
info: func(message: string);
warn: func(message: string);
error: func(message: string);
}
interface host {
use types.{json, plugin-error};
call: func(channel: string, payload: json) -> result<json, plugin-error>;
run-job: func(channel: string, payload: json) -> result<json, plugin-error>;
}
interface lifecycle {
use types.{plugin-error};
init: func() -> result<_, plugin-error>;
}
world plugin {
import log;
import host;
import process;
import progress;
import settings;
import ipc;
export lifecycle;
export commands;
export events;
export settings-changed;
export ui;
export hooks;
export provider;
}

wit.process.wit:
interface process {
use types.{plugin-error};
record exec-output {
status: option<s32>,
stdout: list<u8>,
stderr: list<u8>,
}
enum state {
running,
exited,
killed,
}
record process-status {
state: state,
exit-code: option<s32>,
}
exec: func(program: string, args: list<string>, timeout-ms: u32) -> result<exec-output, plugin-error>;
spawn: func(program: string, args: list<string>, env: list<tuple<string, string>>) -> result<string, plugin-error>;
stop: func(id: string) -> result<_, plugin-error>;
status: func(id: string) -> result<process-status, plugin-error>;
logs: func(id: string, tail: u32) -> result<list<string>, plugin-error>;
%list: func() -> result<list<string>, plugin-error>;
}

wit.providers.wit:
interface provider {
use types.{json, plugin-error};
invoke: func(kind: string, id: string, op: string, args: json) -> result<json, plugin-error>;
}

wit.settings.wit:
interface settings {
use types.{json};
get: func(key: string) -> option<json>;
}
interface settings-changed {
on-settings-changed: func(key: string);
}

wit.ui.wit:
interface ui {
use types.{json, plugin-error};
render: func(page: string, context: json) -> result<json, plugin-error>;
action: func(page: string, action: json, values: json, context: json) -> result<json, plugin-error>;
}
